diff --git a/test.js b/test.js
index e303a46..accf6ee 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,41 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options keeps the active promise and discards every queued function', async t => {
+	const limit = pLimit(1);
+	const executed = [];
+
+	const runningPromise = limit(async () => {
+		await delay(50);
+		executed.push('active');
+		return '🦄';
+	});
+
+	const pendingPromises = Array.from({length: 3}, (_, index) => limit(() => {
+		executed.push(index);
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	// The public API is unchanged: `clearQueue()` still returns nothing.
+	t.is(limit.clearQueue(), undefined);
+
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+
+	// The active promise is untouched and settles with its own result.
+	t.is(await runningPromise, '🦄');
+	t.is(limit.activeCount, 0);
+
+	// Cleared functions are never run, and with `rejectOnClear` disabled their promises never settle.
+	const marker = Symbol('pending');
+	t.is(await Promise.race([...pendingPromises, delay(50, marker)]), marker);
+	t.deepEqual(executed, ['active']);
+	t.is(limit.pendingCount, 0);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
